const list = {{aiCategoriesCatalog}};
const wanted = String({{aiCategoryName}} ?? "").trim().toLowerCase();
if (!Array.isArray(list) || wanted === "no_match") return "";
const found = list.find(item =>
  String(item?.name ?? "").trim().toLowerCase() === wanted
);
return found?.categoryId ?? "";

const list = {{aiProductsCatalog}};
const qty = Number({{aiQuantity}});

if (!Array.isArray(list) || !Number.isInteger(qty) || qty <= 0) {
  return "";
}

const matches = list.filter((item) => {
  const min = Number(item?.minQuantity);
  const max = Number(item?.maxQuantity);

  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    return false;
  }

  return qty >= min && qty <= max;
});

return matches.length === 1
  ? String(matches[0].productId ?? "")
  : "";

const list = {{aiProductsCatalog}};
const id = String({{selectedProductId}} ?? "");

if (!Array.isArray(list) || !id) return "";

const product = list.find(
  item => String(item?.productId ?? "") === id
);

return String(product?.name ?? "");
